function validate([nums, k]) {
  if (nums.length < 1 || nums.length > 50000) return 'nums needs 1 to 50000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each value is a whole number from 1 to 100000.';
  if (!Number.isInteger(k) || k < 1 || k > nums.length) return 'k is between 1 and the length of nums.';
  return null;
}

