function numberOfSubarrays(nums, k) {
  const seen = new Map([[0, 1]]);
  let odds = 0;
  let count = 0;

  for (const num of nums) {
    odds += num % 2;
    count += seen.get(odds - k) ?? 0;
    seen.set(odds, (seen.get(odds) ?? 0) + 1);
  }
  return count;
}

