function numberOfSubarrays(nums, k) {
  let total = 0;
  for (let i = 0; i < nums.length; i++) {
    let oddInside = 0;
    for (let j = i; j < nums.length; j++) {
      if (nums[j] % 2 === 1) oddInside++;
      if (oddInside === k) total++;
      if (oddInside > k) break;
    }
  }
  return total;
}

