function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const top = size === 'large' ? 100000 : (rand() < 0.5 ? 9 : 100000);
  const oddChance = [0.1, 0.3, 0.5, 0.9][Math.floor(rand() * 4)];
  const nums = Array.from({ length: n }, () => {
    const value = 1 + Math.floor(rand() * top);
    const wantOdd = rand() < oddChance;
    if ((value % 2 === 1) === wantOdd) return value;
    return value === top ? value - 1 : value + 1;
  });
  const odd = nums.filter(v => v % 2 === 1).length;
  // Usually ask for a count that exists in the array; sometimes one that may not.
  const k = rand() < 0.8 && odd > 0 ? 1 + Math.floor(rand() * odd) : 1 + Math.floor(rand() * n);
  return [nums, k];
}
